function lesson4Dialogue(){app.innerHTML=intro('HỘI THOẠI · BÀI 4','Thử đồ và trả giá.','Hai hội thoại được chép lại từ các trang bạn gửi.')+lesson2VoiceControls()+'<button class="btn secondary" id="pinyin">'+(showPinyin?'Ẩn':'Hiện')+' pinyin</button>'+lesson4Data.dialogues.map(([title,lines],d)=>'<h2>'+title+'</h2><button class="btn secondary" data-lesson4-full="'+d+'">▶ Nghe toàn hội thoại</button>'+lines.map(([name,zh,py,vi],i)=>'<article class="dialogue"><small>'+name+'</small><button class="text-button" data-lesson4-line="'+d+','+i+'" aria-label="Nghe câu '+(i+1)+'">▶</button><p class="han">'+zh+'</p>'+(showPinyin?'<p class="pinyin">'+py+'</p>':'')+'<p>'+vi+'</p></article>').join('')).join('')+lesson4References(6,9);bindLesson2Voice(lesson4Data.dialogues[0][1].map(l=>l[1]).join(' '));document.querySelector('#pinyin').onclick=()=>{stopWordAudio();showPinyin=!showPinyin;lesson4Dialogue();};document.querySelectorAll('[data-lesson4-line]').forEach(b=>b.onclick=()=>{const[d,i]=b.dataset.lesson4Line.split(',').map(Number);lesson2Speak(lesson4Data.dialogues[d][1][i][1]);});document.querySelectorAll('[data-lesson4-full]').forEach(b=>b.onclick=()=>lesson2Speak(lesson4Data.dialogues[Number(b.dataset.lesson4Full)][1].map(l=>l[1]).join(' ')));}
function lesson4BTNCMarkup(file){const group=lesson4BTNC.find(g=>g.file===file);if(!group)return '<p class="sub">File chính Q2B4; xem phần đáp án BTNC trên trang tham khảo bên dưới.</p>'+lesson4BTNCReference();const id=lesson4BTNC.indexOf(group),saved=state.lesson4Exercises?.['btnc'+id]||{};return '<details class="lesson2-answer-key"><summary>Luyện nghe với 5 câu hỏi</summary><p class="sub">Câu hỏi tự luyện biên soạn từ bản ghi lời nghe, không phải bộ lựa chọn của đề BTNC gốc.</p><form id="lesson4BTNCForm'+id+'">'+group.questions.map((q,i)=>'<fieldset class="question"><legend>'+q[0]+'</legend>'+q[1].map((v,j)=>'<label><input type="radio" name="l4nc'+id+'q'+i+'" value="'+j+'" '+(String(saved[i]?.answer)===String(j)?'checked':'')+'> '+v+'</label>').join('')+'<div id="lesson4BTNCFeedback'+id+'-'+i+'"></div></fieldset>').join('')+'<button class="btn" type="submit">Kiểm tra</button><p id="lesson4BTNCResult'+id+'" role="status"></p></form></details><details class="lesson2-answer-key"><summary>Bản ghi lời nghe và đáp án BTNC gốc</summary>'+group.transcript.map((t,i)=>'<p lang="zh-CN" style="white-space:pre-line">'+(i+1)+'. '+esc(t)+'</p>').join('')+'<p><b>Đáp án '+group.title+':</b> '+group.key.map((k,i)=>(i+1)+'. '+k).join(' · ')+'</p><p class="sub">Các chữ cái dùng đối chiếu với đề BTNC gốc; câu tự luyện phía trên có thứ tự lựa chọn riêng.</p>'+lesson4BTNCReference()+'</details>';}
function lesson4BTNCReference(){return '<details class="lesson2-reference"><summary>Xem trang đáp án BTNC bài 4</summary><img loading="lazy" style="max-width:100%;height:auto" src="images/lesson4/btnc-answers-page15.png" alt="Đáp án BTNC bài 4, trang 15 của PDF"></details>';}
function bindLesson3BTNC(){lesson4BTNC.forEach((group,id)=>{document.querySelector('#lesson4BTNCForm'+id).onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),records={};let count=0;group.questions.forEach((q,i)=>{const answer=form.get('l4nc'+id+'q'+i),correct=answer!==null&&Number(answer)===q[2];records[i]={answer,correct};count+=correct?1:0;document.querySelector('#lesson4BTNCFeedback'+id+'-'+i).innerHTML='<div class="feedback '+(correct?'good':'bad')+'">'+(correct?'✓ Chính xác':'Đáp án: '+esc(q[1][q[2]]))+'</div>';});state.lesson4Exercises=state.lesson4Exercises||{};state.lesson4Exercises['btnc'+id]=records;save();document.querySelector('#lesson4BTNCResult'+id).textContent='Đúng '+count+' / 5 câu.';};});}

const lesson4SourcePages=['39','40','41','41–42','42–43','43–44','44–45','45–46','46–47','47–48','48','49','49–50'];
function lesson4References(first=1,last=13){return '<details class="lesson2-reference"><summary>Xem trang giáo trình gốc</summary>'+Array.from({length:last-first+1},(_,i)=>'<figure><img loading="lazy" src="images/lesson4/source-'+(first+i)+'.png" alt="Bài 4 · ảnh nguồn '+(first+i)+'"><figcaption>Trang '+lesson4SourcePages[first+i-1]+'</figcaption></figure>').join('')+'</details>';}
function lesson4Home(){app.innerHTML=intro('HSK2 · LESSON 4',lesson4Data.title,lesson4Data.pinyin+' · '+lesson4Data.vi)+'<section class="hero"><div><h2>Mua sắm & chọn quần áo</h2><p>Hỏi màu sắc, kích cỡ, thử đồ và trao đổi giá cả.</p><a class="btn" href="#words">Học 19 mục từ →</a></div><div class="hero-mark" aria-hidden="true">衣</div></section><div class="stats"><div class="stat"><small>TỪ ĐÃ NHỚ</small><strong>'+state.known.length+'<small> / 19</small></strong></div><div class="stat"><small>HỘI THOẠI</small><strong>02</strong></div><div class="stat"><small>TRANG GIÁO TRÌNH</small><strong>39–50</strong></div></div><div class="grid">'+[['words','Từ vựng','Nghe & gõ · Flashcard · Ghép từ'],['grammar','Ngữ pháp','Lượng từ · Cấu trúc 的'],['dialogue','Hội thoại','Thử áo sơ mi · Mua giày và trả giá'],['practice','Luyện tập','Điền từ · Đọc hiểu · Mô phỏng mua sắm'],['listening','Luyện nghe','Bốn file Q2B4 · Bản ghi BTNC · Tự luyện'],['writing','Luyện viết','Chữ Hán trong bài 4']].map(([id,title,desc])=>'<a class="card card-link" href="#'+id+'"><h3>'+title+' ↗</h3><p>'+desc+'</p></a>').join('')+'</div><article class="card grammar"><h2>Khởi động</h2><p>你喜欢买东西吗？<br>你常常去哪儿买东西？<br>你常常和谁一起买东西？</p><p class="sub">Bạn có thích mua sắm? Thường mua ở đâu và cùng ai?</p></article>'+lesson4References();}
function lesson4Grammar(){app.innerHTML=intro('NGỮ PHÁP · BÀI 4','Nói về món đồ bạn muốn chọn.','Lượng từ và cách dùng 的 để thay cho danh từ đã biết.')+'<article class="card grammar"><h2>01 · Lượng từ</h2><div class="pattern">Số từ + lượng từ + danh từ</div><p>Lượng từ nằm giữa số từ và danh từ. Mỗi nhóm đồ vật thường đi với lượng từ phù hợp.</p><div class="lesson2-table"><table><thead><tr><th>Lượng từ</th><th>Ví dụ trong sách</th></tr></thead><tbody><tr><td>个</td><td>一个人 / 一个苹果</td></tr><tr><td>只</td><td>一只猫 / 一只狗</td></tr><tr><td>件</td><td>一件衣服 / 一件衬衫</td></tr><tr><td>双</td><td>一双鞋</td></tr><tr><td>家</td><td>一家书店 / 一家饭店</td></tr></tbody></table></div><p class="sub">条 xuất hiện thêm trong bài: 一条裤子 — một chiếc quần. Khi đếm hai món đồ, thường dùng 两: 两件衣服、两双鞋.</p></article><article class="card grammar"><h2>02 · Cấu trúc 的</h2><div class="pattern">Danh từ / đại từ / tính từ + 的</div><p>Khi người nghe đã biết đang nói đến vật gì, có thể lược danh từ phía sau 的.</p><p lang="zh-CN">这双鞋有黑的吗？（黑的＝黑颜色的鞋）<br>我的手机是苹果的。（苹果的＝苹果手机）<br>这件衣服不是我的，是他的。（他的＝他的衣服）</p><p class="sub">Đôi giày này có màu đen không? · Điện thoại của tôi là của Apple. · Chiếc áo này không phải của tôi, mà của anh ấy.</p></article><article class="card grammar"><h2>Mẫu câu mua sắm</h2><p lang="zh-CN">这件衬衫还有什么颜色的？<br>我可以试一下蓝色的吗？<br>您穿什么号的？— 我穿大号的。<br>您穿多大号的？— 我穿38号的。<br>太贵了，可以便宜一点儿吗？<br>我觉得不太合适。</p></article><a class="btn" href="#practice">Luyện chọn đồ →</a>'+lesson4References(3,5);}
let lesson4PracticeMode='vocab';
function gradeLesson4Exercise(mode,index,draft){const q=lesson4Data.exercises[mode][index],variants=[q[1]];if(mode==='choose'&&index===3)variants.push('一点');if(mode==='vocab'&&index===3)variants.push('色');return {correct:variants.some(a=>compareHanzi(draft,a).correct),answer:q[1],note:q[2]};}
function lesson4Practice(){app.innerHTML=intro('LUYỆN TẬP · BÀI 4','Chọn màu, chọn cỡ và trao đổi giá.','Các bài điền từ, đọc hiểu và mô phỏng theo giáo trình.')+'<div class="toolbar lesson2-modes">'+[['vocab','Điền từ'],['reading','Đọc hiểu'],['choose','号 · 一点儿 · 一起 · 一下'],['shop','Mua sắm'],['summary','Tự tổng kết']].map(([id,title])=>'<button class="btn '+(lesson4PracticeMode===id?'':'secondary')+'" data-lesson4-mode="'+id+'">'+title+'</button>').join('')+'</div><div id="lesson4ExerciseArea"></div>';document.querySelectorAll('[data-lesson4-mode]').forEach(b=>b.onclick=()=>{lesson4PracticeMode=b.dataset.lesson4Mode;lesson4Practice();});renderLesson4ExerciseArea();}
function renderLesson4ExerciseArea(){const area=document.querySelector('#lesson4ExerciseArea'),mode=lesson4PracticeMode;if(mode==='shop'){renderLesson4Shop(area);return;}if(mode==='summary'){area.innerHTML='<article class="card grammar"><h2>Từ ngữ và mẫu câu muốn nhớ</h2><label for="lesson4SummaryWords">Từ ngữ</label><textarea id="lesson4SummaryWords" rows="4"></textarea><label for="lesson4SummaryPatterns">Mẫu câu</label><textarea id="lesson4SummaryPatterns" rows="4"></textarea><p class="sub">Tự động lưu trong tiến độ Lesson 4.</p></article>'+lesson4References(13,13);for(const[id,key]of [['lesson4SummaryWords','words'],['lesson4SummaryPatterns','patterns']]){document.querySelector('#'+id).value=state.lesson4Summary?.[key]||'';document.querySelector('#'+id).oninput=e=>{state.lesson4Summary=state.lesson4Summary||{};state.lesson4Summary[key]=e.target.value;save();};}return;}
 const saved=state.lesson4Exercises?.[mode]||{};
 area.innerHTML=(mode==='reading'?'<article class="card grammar"><h2>Đoạn đọc</h2><p class="lesson2-reading" lang="zh-CN">'+lesson4Data.reading+'</p><p class="sub">Từ hỗ trợ: 黄色 (màu vàng), 白色 (màu trắng), 裤子 (quần), 条 (lượng từ cho quần).</p></article>':'')+'<form id="lesson4ExerciseForm">'+lesson4Data.exercises[mode].map((q,i)=>'<article class="card grammar"><label for="lesson4Answer'+i+'">'+(i+1)+'. '+esc(q[0])+'</label><input class="lesson2-answer" id="lesson4Answer'+i+'" lang="zh-CN" placeholder="Gõ chữ Hán…" value="'+esc(saved[i]?.draft||'')+'"><div id="lesson4Feedback'+i+'" role="status"></div></article>').join('')+'<button class="btn" type="submit">Kiểm tra</button><p id="lesson4Result" role="status"></p></form>'+(mode==='reading'?'<h2>Chọn đáp án theo đoạn văn</h2><form id="lesson4ReadingQuiz">'+lesson4Data.exercises.comprehension.map((q,i)=>'<fieldset class="card question"><legend>'+q[0]+'</legend>'+q[1].map((v,j)=>'<label><input type="radio" name="l4reading'+i+'" value="'+j+'"> '+v+'</label>').join('')+'<div id="lesson4ReadingFeedback'+i+'"></div></fieldset>').join('')+'<button class="btn" type="submit">Kiểm tra đọc hiểu</button><p id="lesson4ReadingResult" role="status"></p></form>':'')+lesson4References(mode==='vocab'?2:11,mode==='vocab'?3:13);
 document.querySelector('#lesson4ExerciseForm').onsubmit=e=>{e.preventDefault();const records={};let count=0;lesson4Data.exercises[mode].forEach((q,i)=>{const draft=document.querySelector('#lesson4Answer'+i).value,r=gradeLesson4Exercise(mode,i,draft);records[i]={draft,correct:r.correct};count+=r.correct?1:0;document.querySelector('#lesson4Feedback'+i).innerHTML='<div class="feedback '+(r.correct?'good':'bad')+'">'+(r.correct?'✓ Chính xác':'Đáp án tham khảo: '+esc(r.answer))+'<br>'+esc(r.note)+'</div>';});state.lesson4Exercises=state.lesson4Exercises||{};state.lesson4Exercises[mode]=records;save();document.querySelector('#lesson4Result').textContent='Đúng '+count+' / '+lesson4Data.exercises[mode].length+' câu.';};
 if(mode==='reading')document.querySelector('#lesson4ReadingQuiz').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),records={};let count=0;lesson4Data.exercises.comprehension.forEach((q,i)=>{const answer=form.get('l4reading'+i),correct=answer!==null&&Number(answer)===q[2];records[i]={answer,correct};count+=correct?1:0;document.querySelector('#lesson4ReadingFeedback'+i).innerHTML='<div class="feedback '+(correct?'good':'bad')+'">'+(correct?'✓ Chính xác':'Đáp án: '+esc(q[1][q[2]]))+'</div>';});state.lesson4Exercises=state.lesson4Exercises||{};state.lesson4Exercises.comprehension=records;save();document.querySelector('#lesson4ReadingResult').textContent='Đúng '+count+' / 4 câu.';};
}

function lesson4Listening(){const groups=[{"title":"04-1 · Thử áo sơ mi","d":0,"tf":[["男的想买衣服。","Đúng — muốn mua một chiếc áo sơ mi."],["衬衫没有黑色的。","Sai — có màu đen, đỏ và xanh lam."],["男的试大号的。","Đúng — 田中 mặc cỡ lớn."],["男的觉得都合适。","Sai — anh ấy thấy cả hai đều không vừa lắm."]],"questions":[["男的想买什么衣服？","一件衬衫。"],["衬衫有什么颜色的？","黑色的、红色的和蓝色的。"],["男的穿什么号的？","大号的。"],["他为什么没买？","因为他觉得都不太合适。"]]},{"title":"04-2 · Mua giày và trả giá","d":1,"questions":[["女的想买什么？","一双鞋。"],["女的想试穿什么颜色的？","黑色的。"],["女的觉得这双鞋怎么样？","大小很合适，颜色也不错。"],["女的用多少钱买这双鞋？","350块。"]]}];app.innerHTML=intro('LUYỆN NGHE · BÀI 4','Nghe và luyện theo tình huống.','Bốn file Q2B4 bạn cung cấp, kèm bản ghi BTNC và câu tự luyện.')+'<div class="notice">File Q2B4 thuộc bộ BTNC. Phần bản ghi và đáp án NC1–NC3 được đối chiếu theo PDF bài 4. Chưa xác định bản thu tương ứng mã 04-1, 04-2, 04-3 trong giáo trình.</div>'+['Q2B4.mp3','Q2B4.NC1.MP3','Q2B4.NC2.MP3','Q2B4.NC3.MP3'].map((file,i)=>'<article class="card grammar"><h3>'+file+'</h3><audio controls preload="none" src="audio/'+file+'"></audio><label>Tốc độ <select data-lesson4-audio="'+i+'" aria-label="Tốc độ '+file+'"><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option></select></label>'+lesson4BTNCMarkup(file)+'</article>').join('')+'<h2>Luyện thêm theo văn bản giáo trình</h2>'+lesson2VoiceControls()+groups.map(g=>'<article class="card grammar"><h2>'+g.title+'</h2><button class="btn secondary" data-lesson4-listen="'+g.d+'">▶ Nghe toàn hội thoại bằng giọng thiết bị</button>'+(g.tf?'<h3>Nhận định đúng / sai</h3>'+g.tf.map(([q,a])=>'<details class="lesson2-answer-key"><summary>'+q+'</summary><p>'+a+'</p></details>').join(''):'')+'<h3>Nghe và trả lời</h3>'+g.questions.map(([q,a])=>'<details class="lesson2-answer-key"><summary>'+q+'</summary><p>'+a+'</p></details>').join('')+'<p class="sub">Đối chiếu theo văn bản hội thoại, không phải đáp án từ audio BTNC.</p></article>').join('')+'<article class="card grammar"><h2>04-3 · Bài nghe mở rộng trong giáo trình</h2><p class="notice">Chưa có bản ghi lời nghe xác nhận cho mã 04-3 nên chưa chấm điểm phần này.</p><h3>Đúng / sai</h3><ol><li>男的想买苹果。</li><li>男的想买手机。</li><li>只有黑色的手机。</li><li>男的觉得手机很便宜。</li></ol><h3>Nghe và trả lời</h3><ol><li>男的想买什么手机？</li><li>男的想买什么颜色的？</li><li>男的为什么喜欢这个手机？</li><li>手机多少钱？</li></ol></article>'+lesson4References(10,13);bindLesson3BTNC();document.querySelectorAll('[data-lesson4-audio]').forEach(select=>select.onchange=()=>{document.querySelectorAll('audio')[Number(select.dataset.lesson4Audio)].playbackRate=Number(select.value);});document.querySelectorAll('audio').forEach(audio=>audio.onplay=()=>{stopWordAudio();document.querySelectorAll('audio').forEach(other=>{if(other!==audio)other.pause();});});bindLesson2Voice(lesson4Data.dialogues[0][1].map(l=>l[1]).join(' '));document.querySelectorAll('[data-lesson4-listen]').forEach(b=>b.onclick=()=>lesson2Speak(lesson4Data.dialogues[Number(b.dataset.lesson4Listen)][1].map(l=>l[1]).join(' ')));}
const lesson4ShopItems=[{name:'衬衫',measure:'件',colors:['红色','蓝色'],sizes:['小','中','大']},{name:'鞋',measure:'双',colors:['黑色','蓝色'],sizes:['38','39','40']},{name:'裤子',measure:'条',colors:['白色','绿色'],sizes:['小','中','大']}];
function gradeLesson4Shop(index,draft,item,color){const t=normalizeHanzi(draft);if(index===0)return t.includes('颜色')&&t.includes(item.name)&&t.includes(item.measure);if(index===1)return t.includes('可以')&&t.includes('试')&&t.includes('一下')&&t.includes(color);return (t.includes('贵')||t.includes('便宜'))&&t.includes('便宜')&&(t.includes('一点')||t.includes('350')||t.includes('三百五十'));}
function renderLesson4Shop(area){const saved=state.lesson4Shop||{},item=lesson4ShopItems[Number(saved.item)||0],color=item.colors.includes(saved.color)?saved.color:item.colors[0];area.innerHTML='<article class="card grammar"><h2>Đóng vai khách hàng và nhân viên bán hàng</h2><p class="sub">Theo mẫu tranh trang 42–43: chọn mặt hàng, hỏi màu, xin thử và hỏi cỡ. Phần trả giá luyện theo hội thoại mua giày.</p><div class="toolbar"><label>Mặt hàng <select id="lesson4ShopItem">'+lesson4ShopItems.map((x,i)=>'<option value="'+i+'" '+(x===item?'selected':'')+'>'+x.measure+x.name+'</option>').join('')+'</select></label><label>Màu <select id="lesson4ShopColor">'+item.colors.map(c=>'<option '+(c===color?'selected':'')+'>'+c+'</option>').join('')+'</select></label><label>Cỡ <select id="lesson4ShopSize">'+item.sizes.map(size=>'<option '+(size===saved.size?'selected':'')+'>'+size+'</option>').join('')+'</select></label></div>'+['Hỏi món này còn màu gì khác','Xin thử màu bạn đã chọn','Đề nghị rẻ hơn một chút'].map((label,i)=>'<label for="lesson4ShopAnswer'+i+'">'+(i+1)+'. '+label+'</label><input class="lesson2-answer" id="lesson4ShopAnswer'+i+'" lang="zh-CN" value="'+esc(saved['answer'+i]||'')+'"><p id="lesson4ShopFeedback'+i+'" role="status"></p>').join('')+'<button class="btn" id="lesson4ShopCheck">Kiểm tra mẫu câu</button><details class="lesson2-answer-key"><summary>Xem hội thoại tham khảo</summary><p id="lesson4ShopDialogue"></p></details><h3>Hỏi đáp về sở thích</h3><p>你常常买衣服吗？<br>你喜欢穿什么颜色的衣服？<br>你喜欢去哪儿买衣服？</p></article>'+lesson4References(4,5);
 for(const id of ['Item','Color','Size'])document.querySelector('#lesson4Shop'+id).onchange=()=>{state.lesson4Shop=state.lesson4Shop||{};state.lesson4Shop[id.toLowerCase()]=document.querySelector('#lesson4Shop'+id).value;if(id==='Item'){state.lesson4Shop.color='';state.lesson4Shop.size='';}renderLesson4Shop(area);save();};for(let i=0;i<3;i++)document.querySelector('#lesson4ShopAnswer'+i).oninput=e=>{state.lesson4Shop=state.lesson4Shop||{};state.lesson4Shop['answer'+i]=e.target.value;save();};
 const examples=['请问，这'+item.measure+item.name+'还有什么颜色的？','我可以试一下'+color+'的吗？','太贵了，可以便宜一点儿吗？'];document.querySelector('#lesson4ShopCheck').onclick=()=>{for(let i=0;i<3;i++){const draft=document.querySelector('#lesson4ShopAnswer'+i).value,ok=gradeLesson4Shop(i,draft,item,color);document.querySelector('#lesson4ShopFeedback'+i).textContent=ok?'✓ 符合练习句型 · Đúng mẫu luyện tập.':'Gợi ý: '+examples[i];}save();};document.querySelector('#lesson4ShopDialogue').textContent=examples[0]+' 还有'+item.colors.map(c=>c+'的').join('和')+'。'+examples[1]+' 可以，您穿什么号的？我穿'+(document.querySelector('#lesson4ShopSize').value)+'号的。好的，给您。谢谢！不客气！';}
for(const[route,handler]of Object.entries({home:lesson4Home,grammar:lesson4Grammar,dialogue:lesson4Dialogue,practice:lesson4Practice,listening:lesson4Listening}))pages[route]=function(){if(state.lesson==='4')handler();else lesson4PreviousPages[route]();};
pages.writing=function(){lesson4PreviousPages.writing();if(state.lesson!=='4')return;document.querySelector('#app .eyebrow').textContent='LUYỆN VIẾT · BÀI 4';const chars=[...new Set(lesson4Data.rows.map(r=>r[0]).join('').split(''))];document.querySelector('#model').innerHTML=chars.map(c=>'<option>'+c+'</option>').join('');document.querySelector('#modelchar').textContent=chars[0];};
render();
